from pathlib import Path
from collections import Counter, defaultdict
from urllib.parse import urlsplit
import hashlib,json,re,unicodedata,urllib.request,zipfile
import pyarrow.parquet as pq

pin='e737b94a38cf77b2ec3a29cb1c6bd756fb1329fb'
url='https://huggingface.co/datasets/sarahcen/ai-supply-chain/resolve/'+pin+'/data/gsearch_relationship_results.parquet'
path=Path('/content/data.parquet')
with urllib.request.urlopen(url,timeout=90) as src,path.open('xb') as out:
    while block:=src.read(1048576):out.write(block)
source_sha=hashlib.sha256(path.read_bytes()).hexdigest()
columns='relationship_pass article_title document_date ai_stack_layers relationship_type relationship_status evidence_strength actor_1_type actor_2_type directionality actor_1_name actor_2_name link'.split()
article_support=defaultdict(set);pass_ids=defaultdict(set)
modes={key:defaultdict(set) for key in ('trim','fold')}
stats=Counter()
for batch in pq.ParquetFile(path).iter_batches(columns=columns,batch_size=2048):
    for r in batch.to_pylist():
        stats['input']+=1
        date=str(r['document_date'])[:10]
        layers=r['ai_stack_layers']
        if isinstance(layers,str):
            if layers.startswith('['):layers=json.loads(layers)
            else:layers=[layers]
        if not ('2022-11-01'<=date<='2026-10-31' and 'CAPITAL' in (layers or []) and r['actor_1_type']==r['actor_2_type']=='COMPANY' and r['relationship_status']=='ESTABLISHED' and r['relationship_type']=='INVESTMENT' and r['evidence_strength']=='EXPLICIT' and r['directionality'] in ('ACTOR_1_TO_ACTOR_2','ACTOR_2_TO_ACTOR_1')):continue
        stats['eligible']+=1
        link=urlsplit(r['link'] or '')
        host=(link.hostname or '').lower().removeprefix('www.')
        if not host or link.scheme.lower() not in ('http','https'):continue
        a,b=[(r[key] or '').strip() for key in ('actor_1_name','actor_2_name')]
        if not a or not b:continue
        if r['directionality']=='ACTOR_2_TO_ACTOR_1':a,b=b,a
        for key,graph in modes.items():
            norm=lambda s:' '.join(unicodedata.normalize('NFKC',s).casefold().split()) if key=='fold' else s
            x,y=norm(a),norm(b)
            if x!=y:graph[x,y].add(host)

            if key=='fold' and x!=y:
                pass_ids[x,y,r['link'].strip(),host].add(r['relationship_pass'])
                tokens=re.findall(r'[^\W_]+',unicodedata.normalize('NFKC',r['article_title'] or '').casefold())
                if len(tokens)>=8:article_support[x,y,date,tuple(tokens)].add(host)
group_token=''
pass_token=''
import base64,io
import itertools
import networkx as nx
def from_token(blob):
    with zipfile.ZipFile(io.BytesIO(base64.b64decode(blob))) as z:
        assert z.testzip() is None
        return json.loads(z.read(z.namelist()[0]))
def verify(label,graph,report):
    supports=defaultdict(list)
    for (a,b),units in graph.items():
        assert units
        supports[a].append(tuple(sorted(units)))
    focus=supports['nvidia']
    hosts=sorted(set().union(*map(set,focus)))
    pos={host:j for j,host in enumerate(hosts)}
    cases=report['individuals'];remaining=set(supports)-set(cases)-{'nvidia'}
    tail_degree=max(len(supports[a]) for a in remaining)
    if 'tail_max_degree' in report:assert report['tail_max_degree']==tail_degree
    if 'tail_max' in report:assert report['tail_max']==tail_degree
    bounds=[]
    for name,baseline,resp in [(a,len(supports[a]),r) for a,r in cases.items()]+[(None,tail_degree,report['tail'])]:
        inc=Counter(focus)
        if name:inc.subtract(s for s in supports[name] if all(h in pos for h in s))
        endrow={};system=[];col=len(hosts)
        for support,coef in sorted(inc.items()):
            if not coef:continue
            cols=[pos[h] for h in support]
            if len(cols)==1:endrow[cols[0]]=-coef;continue
            endrow[col]=-coef
            if coef>0:
                for j in cols:system.append(({col:1,j:-1},0))
            else:system.append((dict([(j,1) for j in cols]+[(col,-1)]),len(cols)-1))
            col+=1
        system.append((endrow,baseline-len(focus)))
        reduced=[1000000]*len(hosts)+[0]*(col-len(hosts))
        value=0
        for row,mult in resp['multipliers']:
            assert type(row)==int and 0<=row<len(system) and type(mult)==int and mult>=0
            terms,right=system[row]
            value-=mult*right
            for j,coeff in terms.items():reduced[j]+=coeff*mult
        value+=sum(min(x,0) for x in reduced)
        assert value==resp['fraction_numerator']
        bounds.append(-(-value//1000000))
    n=min(bounds)
    omit=set(report['witness']['groups'])
    assert len(omit)==n==report['lower']==report['upper']
    degrees=Counter(a for (a,b),units in graph.items() if units-omit)
    top=max(degrees.values())
    leaders=sorted(a for a,score in degrees.items() if score==top)
    assert 'nvidia' not in leaders or len(leaders)>1
    assert leaders==report['leaders_after']
    return dict(scenario=label,pairs=len(graph),nvidia_initial=len(focus),nvidia_final=degrees['nvidia'],leaders=leaders,top=top,minimum=n,individuals_checked=len(cases),tail_size=len(remaining))
base=modes['fold']
assert source_sha=='89752ca13ef5516cf22805616a5976b0fecc717c4fecb29e739bc7297385f56a' and len(base)==6417
groups=from_token(group_token)['results']
results=[]
signatures=defaultdict(set)
for (a,b,day,title),seen in article_support.items():
    for h,j in itertools.combinations(sorted(seen),2):
        signatures[h,j].add((day,title))
allhosts=set().union(*base.values())
for cutoff in (1,2):
    edge=nx.Graph();edge.add_nodes_from(allhosts)
    edge.add_edges_from((h,j) for (h,j),days in signatures.items() if len(days)>=cutoff)
    cmap={h:min(component) for component in nx.connected_components(edge) for h in component}
    expected=groups[str(cutoff)]
    assert sorted(sorted(s) for s in nx.connected_components(edge) if len(s)>1)==sorted(expected['joined_groups'])
    transformed={k:{cmap[h] for h in hs} for k,hs in base.items()}
    results.append(verify('headline'+str(cutoff),transformed,expected))
g=defaultdict(set)
for (a,b,url,h),repeat in pass_ids.items():
    if repeat=={1,2}:g[a,b].add(h)
results.append(verify('exact_url_two_passes',g,from_token(pass_token)))
archive=Path('/content/joint-audit.zip')
with zipfile.ZipFile(archive,'x',zipfile.ZIP_DEFLATED) as z:z.writestr('audit.json',json.dumps({'pin':pin,'input_sha256':source_sha,'results':results},sort_keys=True))
print('archive_sha256 '+hashlib.sha256(archive.read_bytes()).hexdigest())
